import{_ as t,c as o,o as a,a5 as r}from"./chunks/framework.CUJoMJm2.js";const m=JSON.parse('{"title":"ADR 006: Canonical RPC Envelope over MessageFrame","description":"","frontmatter":{},"headers":[],"relativePath":"adr/006-rpc-envelope.md","filePath":"adr/006-rpc-envelope.md","lastUpdated":1768070912000}'),n={name:"adr/006-rpc-envelope.md"};function s(i,e,c,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-006-canonical-rpc-envelope-over-messageframe" tabindex="-1">ADR 006: Canonical RPC Envelope over MessageFrame <a class="header-anchor" href="#adr-006-canonical-rpc-envelope-over-messageframe" aria-label="Permalink to “ADR 006: Canonical RPC Envelope over MessageFrame”">​</a></h1><ul><li><strong>Date</strong>: 2025-11-23</li><li><strong>Status</strong>: Accepted</li><li><strong>Applies to</strong>: RPC</li><li><strong>Tags</strong>: rpc, protocol-usage, type-safety</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>MessageFrame</code> is intentionally generic (subject + opaque bytes) to keep the protocol minimal and stable. However, RPC users currently parse subject conventions manually and re-implement correlation and error handling in userland, violating &quot;hard to misuse APIs.&quot;</p><p>The question is where to fix this: at the protocol layer (new frame kinds) or at the RPC layer (canonical envelope structure).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><p><strong>Keep <code>MessageFrame</code> unchanged</strong> – the one and only application-level payload frame.</p></li><li><p><strong>Define a canonical RPC envelope</strong> carried in <code>MessageFrame.data</code>: Request, Success Response, Error Response, Notification. Encoded as JSON (v1) or CBOR (v2+).</p></li><li><p><strong>Enforce subject namespacing</strong>: all messages must start with <code>rpc/</code>, <code>event/</code>, <code>stream/</code>, or <code>app/</code>. Invalid subjects → <code>ProtocolViolation</code>.</p></li><li><p><strong>Zero protocol wire changes.</strong> RPC semantics live at the <code>@sideband/rpc</code> layer, not the wire.</p></li></ol><h3 id="subject-namespace-mandatory-runtime-validated" tabindex="-1">Subject Namespace (Mandatory, Runtime-Validated) <a class="header-anchor" href="#subject-namespace-mandatory-runtime-validated" aria-label="Permalink to “Subject Namespace (Mandatory, Runtime-Validated)”">​</a></h3><p>All <code>MessageFrame.subject</code> values must match one of these prefixes:</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Purpose</th><th>Example</th><th>Allowed senders</th><th>Semantics</th></tr></thead><tbody><tr><td><code>rpc/</code></td><td>RPC request/response</td><td><code>rpc/getUser</code></td><td>both</td><td>Request/Response</td></tr><tr><td><code>event/</code></td><td>Fire-and-forget pub/sub event</td><td><code>event/user.joined</code></td><td>both</td><td>Notification</td></tr><tr><td><code>stream/</code></td><td>Streaming (reserved for v2)</td><td><code>stream/abc123/chunk</code></td><td>reserved</td><td>(future)</td></tr><tr><td><code>app/</code></td><td>Vendor-specific (fallback)</td><td><code>app/com.example/mydata</code></td><td>both</td><td>Custom semantics</td></tr></tbody></table><p>Subjects outside these prefixes are rejected at runtime with <code>ProtocolViolation</code>.</p><h3 id="envelope-schema" tabindex="-1">Envelope Schema <a class="header-anchor" href="#envelope-schema" aria-label="Permalink to “Envelope Schema”">​</a></h3><p>Request (<code>t: &quot;r&quot;</code>): method name + optional params. Success Response (<code>t: &quot;R&quot;</code>): optional result. Error Response (<code>t: &quot;E&quot;</code>): code + message + optional data. Notification (<code>t: &quot;N&quot;</code>): event name + optional data.</p><p>Correlation is explicit: responses copy the request&#39;s <code>cid</code> (correlation ID) field. The <code>cid</code> field is set to the request frame&#39;s own <code>frameId</code> and copied unchanged by the server into all response envelopes.</p><p>See ADR-010 for the complete correlation design rationale.</p><p>Full schema at <code>docs/protocols/rpc/envelope.md</code>.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Zero wire changes</strong>: protocol stays minimal and stable.</li><li><strong>Type-safe RPC</strong>: branded types + runtime validation enforce correctness.</li><li><strong>Predictable, hard-to-misuse</strong>: subjects and envelopes validated at runtime.</li><li><strong>Respects layering</strong>: RPC semantics belong above the protocol, not in it.</li><li><strong>Future-proof</strong>: envelope extensible for v2 (CBOR, streaming, etc.) without protocol bumps.</li></ul><h2 id="rationale-for-rejection-of-alternatives" tabindex="-1">Rationale for Rejection of Alternatives <a class="header-anchor" href="#rationale-for-rejection-of-alternatives" aria-label="Permalink to “Rationale for Rejection of Alternatives”">​</a></h2><p><strong>New frame kinds (Request/Response/Notification)</strong>: Pushes RPC semantics into the protocol, violating the minimal charter and hardening patterns that should remain flexible.</p><p><strong>JSON-RPC 2.0</strong>: Verbose, opaque to the protocol, no benefit over a canonical envelope at the RPC layer.</p>',21)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
